1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { upsertSidebarOrderPreferenceSchema } from "@paperclipai/shared";
4	import { forbidden } from "../errors.js";
5	import { assertCompanyAccess } from "./authz.js";
6	import { logActivity, sidebarPreferenceService } from "../services/index.js";
7	import { expressHandler } from "../http/express-adapter.js";
8	import type { Handler, RequestCtx } from "../http/types.js";
9	import type { StorageService } from "../storage/types.js";
10	
11	/** Asserts board actor with a userId and returns the userId. */
12	function requireBoardUserIdCtx(ctx: RequestCtx): string {
13	  if (ctx.actor?.type !== "board") {
14	    throw forbidden("Board access required");
15	  }
16	  if (!ctx.actor.userId) {
17	    throw forbidden("Board user context required");
18	  }
19	  return ctx.actor.userId;
20	}
21	
22	function buildHandlers(db: Db) {
23	  const svc = sidebarPreferenceService(db);
24	
25	  // server/src/routes/sidebar-preferences.ts:21
26	  const getSidebarPreferencesMe: Handler = async (ctx) => {
27	    const userId = requireBoardUserIdCtx(ctx);
28	    return Response.json(await svc.getCompanyOrder(userId));
29	  };
30	
31	  // server/src/routes/sidebar-preferences.ts:27
32	  const putSidebarPreferencesMe: Handler = async (ctx) => {
33	    const userId = requireBoardUserIdCtx(ctx);
34	    const body = await ctx.json();
35	    const parsed = upsertSidebarOrderPreferenceSchema.parse(body);
36	    return Response.json(await svc.upsertCompanyOrder(userId, parsed.orderedIds));
37	  };
38	
39	  // server/src/routes/sidebar-preferences.ts:33
40	  const getCompanySidebarPreferencesMe: Handler = async (ctx) => {
41	    const companyId = ctx.param("companyId") ?? "";
42	    assertCompanyAccess(ctx, companyId);
43	    const userId = requireBoardUserIdCtx(ctx);
44	    return Response.json(await svc.getProjectOrder(companyId, userId));
45	  };
46	
47	  // server/src/routes/sidebar-preferences.ts:41
48	  const putCompanySidebarPreferencesMe: Handler = async (ctx) => {
49	    const companyId = ctx.param("companyId") ?? "";
50	    assertCompanyAccess(ctx, companyId);
51	    const userId = requireBoardUserIdCtx(ctx);
52	
53	    const body = await ctx.json();
54	    const parsed = upsertSidebarOrderPreferenceSchema.parse(body);
55	    const result = await svc.upsertProjectOrder(companyId, userId, parsed.orderedIds);
56	
57	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
58	    const actorId = ctx.actor!.type === "agent"
59	      ? (ctx.actor!.agentId ?? "unknown-agent")
60	      : (ctx.actor!.userId ?? "board");
61	    await logActivity(db, {
62	      companyId,
63	      actorType,
64	      actorId,
65	      agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
66	      runId: ctx.actor?.runId ?? null,
67	      action: "sidebar_preferences.project_order_updated",
68	      entityType: "company",
69	      entityId: companyId,
70	      details: {
71	        userId,
72	        orderedIds: result.orderedIds,
73	      },
74	    });
75	    return Response.json(result);
76	  };
77	
78	  return { getSidebarPreferencesMe, putSidebarPreferencesMe, getCompanySidebarPreferencesMe, putCompanySidebarPreferencesMe };
79	}
80	
81	export function sidebarPreferenceRoutes(db: Db) {
82	  const router = Router();
83	  const {
84	    getSidebarPreferencesMe,
85	    putSidebarPreferencesMe,
86	    getCompanySidebarPreferencesMe,
87	    putCompanySidebarPreferencesMe,
88	  } = buildHandlers(db);
89	
90	  const storageSentinel = new Proxy({} as StorageService, {
91	    get(_target, prop) {
92	      throw new Error(`sidebarPreference handler unexpectedly accessed storage.${String(prop)}`);
93	    },
94	  });
95	  const deps = { db, storage: storageSentinel };
96	
97	  router.get("/sidebar-preferences/me", expressHandler(getSidebarPreferencesMe, deps));
98	  router.put("/sidebar-preferences/me", expressHandler(putSidebarPreferencesMe, deps));
99	  router.get("/companies/:companyId/sidebar-preferences/me", expressHandler(getCompanySidebarPreferencesMe, deps));
100	  router.put("/companies/:companyId/sidebar-preferences/me", expressHandler(putCompanySidebarPreferencesMe, deps));
101	
102	  return router;
103	}
